DO $$ BEGIN DROP POLICY IF EXISTS profiles_select_own ON public.profiles; CREATE POLICY profiles_select_own ON public.profiles FOR SELECT USING (id = auth.uid() OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS profiles_insert_own ON public.profiles; CREATE POLICY profiles_insert_own ON public.profiles FOR INSERT WITH CHECK ((id = auth.uid() AND role = 'CUSTOMER') OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS profiles_update_own ON public.profiles; CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE USING (id = auth.uid() OR public.is_admin()) WITH CHECK (id = auth.uid() OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS shops_read_public ON public.shops; CREATE POLICY shops_read_public ON public.shops FOR SELECT USING (owner_id = auth.uid() OR public.is_admin() OR NOT public.is_shop_owner()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS shops_owner_insert ON public.shops; CREATE POLICY shops_owner_insert ON public.shops FOR INSERT WITH CHECK (owner_id = auth.uid() AND public.is_shop_owner()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS shops_owner_update ON public.shops; CREATE POLICY shops_owner_update ON public.shops FOR UPDATE USING (owner_id = auth.uid() OR public.is_admin()) WITH CHECK (owner_id = auth.uid() OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS shops_owner_delete ON public.shops; CREATE POLICY shops_owner_delete ON public.shops FOR DELETE USING (owner_id = auth.uid() OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS categories_read_public ON public.categories; CREATE POLICY categories_read_public ON public.categories FOR SELECT USING (true); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS products_read_public ON public.products; CREATE POLICY products_read_public ON public.products FOR SELECT USING ((status = 'ACTIVE' AND NOT public.is_shop_owner()) OR EXISTS (SELECT 1 FROM public.shops s WHERE s.id = shop_id AND s.owner_id = auth.uid()) OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS products_owner_write ON public.products; CREATE POLICY products_owner_write ON public.products FOR ALL USING (EXISTS (SELECT 1 FROM public.shops s WHERE s.id = shop_id AND (s.owner_id = auth.uid() OR public.is_admin()))) WITH CHECK (EXISTS (SELECT 1 FROM public.shops s WHERE s.id = shop_id AND (s.owner_id = auth.uid() OR public.is_admin()))); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS inventory_read_public ON public.inventory; CREATE POLICY inventory_read_public ON public.inventory FOR SELECT USING (EXISTS (SELECT 1 FROM public.products p WHERE p.id = product_id AND (p.status = 'ACTIVE' OR EXISTS (SELECT 1 FROM public.shops s WHERE s.id = p.shop_id AND s.owner_id = auth.uid()) OR public.is_admin()))); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS inventory_owner_write ON public.inventory; CREATE POLICY inventory_owner_write ON public.inventory FOR ALL USING (EXISTS (SELECT 1 FROM public.products p JOIN public.shops s ON s.id = p.shop_id WHERE p.id = product_id AND (s.owner_id = auth.uid() OR public.is_admin()))) WITH CHECK (EXISTS (SELECT 1 FROM public.products p JOIN public.shops s ON s.id = p.shop_id WHERE p.id = product_id AND (s.owner_id = auth.uid() OR public.is_admin()))); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS addresses_own ON public.addresses; CREATE POLICY addresses_own ON public.addresses FOR ALL USING (customer_id = auth.uid() OR public.is_admin()) WITH CHECK (customer_id = auth.uid() OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS carts_own ON public.carts; CREATE POLICY carts_own ON public.carts FOR ALL USING (customer_id = auth.uid() OR public.is_admin()) WITH CHECK (customer_id = auth.uid() OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS cart_items_own ON public.cart_items; CREATE POLICY cart_items_own ON public.cart_items FOR ALL USING (EXISTS (SELECT 1 FROM public.carts c WHERE c.id = cart_id AND c.customer_id = auth.uid()) OR public.is_admin()) WITH CHECK (EXISTS (SELECT 1 FROM public.carts c WHERE c.id = cart_id AND c.customer_id = auth.uid()) OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS orders_customer_or_shop ON public.orders; CREATE POLICY orders_customer_or_shop ON public.orders FOR SELECT USING (customer_id = auth.uid() OR EXISTS (SELECT 1 FROM public.shops s WHERE s.id = shop_id AND s.owner_id = auth.uid()) OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS orders_customer_insert ON public.orders; CREATE POLICY orders_customer_insert ON public.orders FOR INSERT WITH CHECK (customer_id = auth.uid()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS offers_read_public ON public.offers; CREATE POLICY offers_read_public ON public.offers FOR SELECT USING (EXISTS (SELECT 1 FROM public.shops s WHERE s.id = shop_id AND s.owner_id = auth.uid()) OR public.is_admin() OR NOT public.is_shop_owner()); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS offers_owner_write ON public.offers; CREATE POLICY offers_owner_write ON public.offers FOR ALL USING (EXISTS (SELECT 1 FROM public.shops s WHERE s.id = shop_id AND (s.owner_id = auth.uid() OR public.is_admin()))) WITH CHECK (EXISTS (SELECT 1 FROM public.shops s WHERE s.id = shop_id AND (s.owner_id = auth.uid() OR public.is_admin()))); EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS notifications_own ON public.notifications; CREATE POLICY notifications_own ON public.notifications FOR ALL USING (user_id = auth.uid() OR public.is_admin()) WITH CHECK (user_id = auth.uid() OR public.is_admin()); EXCEPTION WHEN undefined_object THEN null; END $$;

