DO $$ BEGIN DROP POLICY IF EXISTS product_images_read ON storage.objects; EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS product_images_manage ON storage.objects; EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS product_images_insert ON storage.objects; EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS product_images_write ON storage.objects; EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS shop_images_read ON storage.objects; EXCEPTION WHEN undefined_object THEN null; END $$;
DO $$ BEGIN DROP POLICY IF EXISTS shop_images_manage ON storage.objects; EXCEPTION WHEN undefined_object THEN null; END $$;

CREATE POLICY product_images_read ON storage.objects FOR SELECT USING (bucket_id = 'product-images' AND auth.uid() IS NOT NULL);
CREATE POLICY product_images_write ON storage.objects FOR ALL USING (bucket_id = 'product-images' AND auth.uid() IS NOT NULL) WITH CHECK (bucket_id = 'product-images' AND auth.uid() IS NOT NULL);
CREATE POLICY shop_images_read ON storage.objects FOR SELECT USING (bucket_id = 'shop-images' AND auth.uid() IS NOT NULL);
CREATE POLICY shop_images_manage ON storage.objects FOR ALL USING (bucket_id = 'shop-images' AND auth.uid() IS NOT NULL) WITH CHECK (bucket_id = 'shop-images' AND auth.uid() IS NOT NULL);
